using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using System.Text;
using Railbound.UI;
using Railbound.Networking;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        if (EditorApplication.isPlaying) { ctx.ReturnValue = "playing"; return; }

        var scene = EditorSceneManager.OpenScene("Assets/Project/GameLobby.unity");

        Transform FindDeep(string name)
        {
            foreach (var t in Resources.FindObjectsOfTypeAll<Transform>())
            {
                if (EditorUtility.IsPersistent(t.gameObject)) continue;
                if (t.name == name) return t;
            }
            return null;
        }

        var yellow = FindDeep("Yellow_HUD_Root");
        sb.AppendLine("yellow active=" + (yellow != null && yellow.gameObject.activeSelf));

        var hud = yellow != null ? yellow.GetComponent<RailboundYellowHUDController>() : null;
        if (hud == null) { ctx.ReturnValue = "no hud"; return; }
        ctx.RegisterObjectModification(hud);

        var so = new SerializedObject(hud);
        var customRoot = FindDeep("Customization_UI_Root");
        var customProp = so.FindProperty("customizationPanelRoot");
        if (customProp != null && customRoot != null)
        {
            customProp.objectReferenceValue = customRoot.gameObject;
            sb.AppendLine("wired customizationPanelRoot");
        }

        void EnsureHover(Transform t)
        {
            if (t == null) return;
            var btn = t.GetComponent<Button>() ?? t.GetComponentInChildren<Button>(true);
            if (btn == null) return;
            if (btn.GetComponent<TacticalUIHoverEffect>() == null)
            {
                var h = btn.gameObject.AddComponent<TacticalUIHoverEffect>();
                ctx.RegisterObjectCreation(h);
                sb.AppendLine("hover +" + btn.name);
            }
        }
        EnsureHover(FindDeep("Btn_Deploy"));
        EnsureHover(FindDeep("Nav_PLAY"));
        EnsureHover(FindDeep("Nav_OPERATORS"));
        EnsureHover(FindDeep("Row_InvitePlayer"));

        var customUi = Object.FindObjectOfType<LobbyCustomizationUI>(true);
        sb.AppendLine("customUi=" + (customUi != null) + " on=" + (customUi != null ? customUi.gameObject.name : ""));
        if (customUi != null)
        {
            ctx.RegisterObjectModification(customUi);
            var cso = new SerializedObject(customUi);
            void WireBtn(string prop, params string[] names)
            {
                var p = cso.FindProperty(prop);
                if (p == null || p.objectReferenceValue != null) return;
                foreach (var n in names)
                {
                    var t = FindDeep(n);
                    if (t == null) continue;
                    var b = t.GetComponent<Button>() ?? t.GetComponentInChildren<Button>(true);
                    if (b == null) continue;
                    p.objectReferenceValue = b;
                    sb.AppendLine("custom wire " + prop + "->" + n);
                    return;
                }
            }
            WireBtn("prevOperatorButton", "Btn_PrevOperator", "Button_Prev", "PrevOperator");
            WireBtn("nextOperatorButton", "Btn_NextOperator", "Button_Next", "NextOperator");
            WireBtn("emoteSaluteButton", "Btn_EmoteSalute", "Btn_Salute");
            WireBtn("emoteWaveButton", "Btn_EmoteWave", "Btn_Greet");
            WireBtn("emoteFlexButton", "Btn_EmoteFlex", "Btn_Flex");
            WireBtn("emoteVictoryButton", "Btn_EmoteVictory", "Btn_Victory");
            cso.ApplyModifiedPropertiesWithoutUndo();

            int nulls = 0, set = 0;
            var it = cso.GetIterator();
            bool enter = true;
            while (it.NextVisible(enter))
            {
                enter = false;
                if (it.propertyType == SerializedPropertyType.ObjectReference)
                {
                    if (it.objectReferenceValue == null) nulls++; else set++;
                }
            }
            sb.AppendLine("customUi refs set=" + set + " null=" + nulls);
        }

        var preview = Object.FindObjectOfType<LobbyCharacterPreviewManager>(true);
        if (preview != null)
        {
            var pso = new SerializedObject(preview);
            sb.AppendLine("preview ops=" + pso.FindProperty("operators").arraySize + " anchor=" + (pso.FindProperty("characterSpawnAnchor").objectReferenceValue != null));
        }

        var mm = Object.FindObjectOfType<LobbyMatchmakingController>(true);
        sb.AppendLine("matchmaking=" + (mm != null));

        if (yellow != null && !yellow.gameObject.activeSelf)
        {
            yellow.gameObject.SetActive(true);
            ctx.RegisterObjectModification(yellow.gameObject);
        }
        var legacy = FindDeep("Canvas_Lobby_Legacy");
        if (legacy != null && legacy.gameObject.activeSelf)
        {
            legacy.gameObject.SetActive(false);
            ctx.RegisterObjectModification(legacy.gameObject);
        }

        so.ApplyModifiedPropertiesWithoutUndo();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        sb.AppendLine("saved");
        ctx.ReturnValue = sb.ToString();
    }
}
